def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_last, op_last = history[-1]

    oppD = 0
    myD = 0
    aDC = 0
    aDD = 0

    for i in range(n):
        m, o = history[i]
        if o == 'D':
            oppD += 1
        if m == 'D':
            myD += 1
        if i:
            pm = history[i - 1][0]
            if pm == 'D':
                if o == 'C':
                    aDC += 1
                else:
                    aDD += 1

    my_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_streak += 1
        else:
            break

    op_streak_D = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            op_streak_D += 1
        else:
            break

    op_streak_C = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            op_streak_C += 1
        else:
            break

    k = n if n < 10 else 10
    rec_oppD = 0
    rec_myD = 0
    for i in range(n - k, n):
        m, o = history[i]
        if o == 'D':
            rec_oppD += 1
        if m == 'D':
            rec_myD += 1

    if oppD * 5 >= n * 2 or rec_oppD >= 6 or op_streak_D >= 3:
        return 'D'

    if op_last == 'C' and n >= 95:
        if oppD == 0 or (aDC > 0 and aDC >= aDD):
            return 'D'

    if op_last == 'D':
        if my_last == 'D':
            return 'C'
        if n >= 2 and history[-2][0] == 'D':
            return 'C'
        if rec_myD > 0 and oppD <= max(2, n // 5):
            return 'C'
        return 'D'

    if my_streak == 0:
        if oppD == 0 and n >= 8:
            return 'D'

        if n >= 2 and history[-2][0] == 'D' and history[-1][1] == 'C':
            if aDC > aDD and oppD <= max(2, n // 7):
                return 'D'

        if (
            oppD <= max(2, n // 7)
            and op_streak_C >= 8
            and aDC > 0
            and aDC >= aDD
            and myD < max(4, n // 6)
        ):
            return 'D'
    else:
        if oppD == 0 and aDC > 0 and op_streak_C >= 2:
            return 'D'

        if (
            aDC > 0
            and aDC >= aDD
            and oppD <= max(2, n // 7)
            and op_streak_C >= 2
            and my_streak <= 2
            and myD <= max(6, n // 5)
        ):
            return 'D'

    return 'C'
